script:
frappe.ui.form.on('Purchase Order', {
    refresh: function(frm) {
        frm.page.set_primary_action(__('Print'), function() {

            let po = frm.doc.name || "";
            let supplier = frm.doc.supplier_name || "";
            let project = frm.doc.project || "";
            let qtn = frm.doc.quotation_no || "";

            let file_name = `${po}_${supplier}_${project}_${qtn}`.replace(/ /g, "_");

            let print_url = `/api/method/frappe.utils.print_format.download_pdf?doctype=Purchase Order&name=${frm.doc.name}&format=Standard&no_letterhead=0&_lang=en&filename=${file_name}`;

            window.open(print_url);
        });
    }
});
